// Authoring only. Rebuilding candidates never approves or publishes them.
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
const out = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(out, '../../..');
const inventory = JSON.parse(await fs.readFile(path.join(root, 'data/extracted/inventory.json'), 'utf8'));
const docs = new Map();
for (const entry of inventory) docs.set(entry.articleId, JSON.parse(await fs.readFile(path.join(root, 'data/extracted', entry.outputFile), 'utf8')));
const main = 'article-d0d500126a80';
const SBD = 'article-d4b0c4f9d75f', ART = 'article-94e7a19d8878', CHIP = 'article-eca18e5843e2', INTERACT = 'article-48bdcebcffc6', OP = 'article-39adb0cfa84e', HCI = 'article-e13c3cb65c28';
function ev(id, page, start, end) {
  const text = docs.get(id).pages.find(item => item.page === page).text;
  const from = text.indexOf(start), to = text.indexOf(end, from);
  if (from < 0 || to < from) throw new Error(`${id} p${page}: ${start} ... ${end}`);
  return { page, text: text.slice(from, to + end.length) };
}
const p = (page, start, end) => ev(main, page, start, end);
function source(id, sections, evidence) {
  const doc = docs.get(id);
  return { file: doc.file, title: doc.title, pages: [...new Set(evidence.map(item => item.page))], sections: [sections], evidence: evidence.map(item => item.text) };
}
const related = (id, sections, evidence) => ({ articleId: id, source: source(id, sections, evidence) });
const cards = [];
function add(question, answer, section, evidence, relatedSources = []) {
  cards.push({ id: `${main}-${String(cards.length + 9).padStart(2, '0')}`, articleId: main, question, answer, source: source(main, section, evidence), kind: relatedSources.length ? 'synthesis' : 'direct', ...(relatedSources.length ? { relatedSources } : {}) });
}
const intro = '1 Introduction', cls = '2.1 Identification and Classification Work', edu = '2.2 Awareness and Education Initiatives', ethical = '2.3 Ethical, Legal, and Health Considerations', action = '3 A Call To Action: Why (and How) We Can (and Should) Go Beyond Our Current Efforts', collab = '3.1 Collaboration to Document Positive Patterns and Share Working Examples of Ethical Game Design Elements', tools = '3.2 Development of Software Artifacts to Foster Real-Time Awareness on Users and Developers', measures = '3.3 Advancing Methods and Measures for Assessing Dark Pattern Prevalence and Player Experience, Including Well-Being', agenda = '4 Forging Ahead: A Research Agenda';

add('Como o position paper enfrenta o argumento de que combater padrões enganosos seria incompatível com os modelos de negócio dos jogos?',
'O artigo reconhece [[pressões econômicas e tensões éticas]] relatadas no desenvolvimento, especialmente em jogos como serviço, e registra a percepção de que contramedidas seriam pouco realistas. Sua posição é que esse diagnóstico não deve encerrar antecipadamente a investigação de alternativas aplicáveis ao fluxo de trabalho. A pergunta de pesquisa passa a ser [[como desenvolver e testar contramedidas incorporáveis na prática]], considerando também sustentabilidade dos desenvolvedores. Trata-se de uma defesa programática: o texto não demonstra que qualquer alternativa ética necessariamente preserve receita ou resolva o conflito econômico.', intro,
[p(2, 'Indeed, some have argued', '[ 9 , 31 ], alongside\n\nbroad consensus on the need for mitigation policies [ 31 ].'), p(2, 'This position paper directly challenges', 'game development workflow.')]);

add('Que limite de estratégias regulatórias é ilustrado pelo relato sobre loot boxes na Bélgica, e qual cautela é necessária ao usar esse exemplo na arguição?',
'O texto relata que a proibição belga de loot boxes pagas foi descrita pelas pesquisas citadas como amplamente ineficaz, associando o problema a [[baixa conformidade da indústria, dificuldades de fiscalização por financiamento e escala e possibilidade de contornar bloqueios técnicos]]. O exemplo sustenta a necessidade de investigar outras frentes articuladas de intervenção, em vez de supor que uma regra formal se execute sozinha. É um [[relato contextual de literatura usado pelo position paper]], não uma verificação atual da legislação belga nem prova de que toda regulação seja inútil.', intro,
[p(2, 'Indeed, some have argued', '[ 9 , 31 ], alongside\n\nbroad consensus on the need for mitigation policies [ 31 ].')]);

add('Por que o avanço das taxonomias não implica que os métodos de detecção já identifiquem todos os padrões enganosos?',
'O artigo descreve uma evolução de taxonomias simples para categorias que consideram plataformas digitais e vieses cognitivos, mas ressalta que ainda se procura uma classificação universalmente aceita. Em paralelo, a detecção passou de procedimentos manuais para abordagens semi ou totalmente automatizadas. Mesmo assim, o texto cita estudos segundo os quais ferramentas então examinadas detectavam [[45% dos padrões conhecidos]], sinalizando necessidade de modelos mais robustos. Esse número é [[uma informação da literatura referida no documento]], e não uma taxa universal ou atual de acerto de qualquer detector.', cls,
[p(4, 'The classification field has advanced', 'the need for more robust detection models.')]);

add('Que contribuição o Dark Pattern Analysis Framework traz à discussão de classificação apresentada na agenda, e o que essa contribuição ainda não comprova?',
'Como exemplo de avanço classificatório, o position paper descreve o [[Dark Pattern Analysis Framework, com 68 tipos de padrões e exemplos específicos de jogos]], incluindo 20 tipos a mais em relação à taxonomia de Gray e colegas mencionada no texto. A mesma passagem aponta trabalhos sobre realidade aumentada e virtual e sobre a interação com vieses cognitivos. Esse repertório amplia a capacidade de descrever e reconhecer problemas. Entretanto, [[catalogar mais padrões não equivale a demonstrar eficácia de contramedidas]]; a necessidade de pesquisas de intervenção permanece na argumentação do artigo.', cls,
[p(3, 'Another example is the Dark Pattern Analysis Framework', 'and suggesting ethical interventions [ 26 ].'), p(4, 'The classification field has advanced', 'the need for more robust detection models.')]);

add('Qual papel os vieses cognitivos e as particularidades das plataformas têm no mapeamento de padrões enganosos descrito pelo position paper?',
'A revisão apresentada no artigo destaca que classificar padrões requer atenção tanto a [[formas tradicionais e emergentes de interação, como realidade aumentada e virtual]], quanto a características do jogo que podem intensificar seus efeitos. Também aponta pesquisas que investigam quando os usuários ficam mais suscetíveis à manipulação por sua interação com vieses cognitivos. Isso sugere um mapeamento sensível ao contexto e aos mecanismos de influência, em vez de uma lista puramente visual. O texto apresenta essa direção da literatura; [[não fornece neste artigo um experimento próprio que quantifique cada viés]].', cls,
[p(3, 'Another example is the Dark Pattern Analysis Framework', 'and suggesting ethical interventions [ 26 ].')]);

add('Como a formação de designers e profissionais de UX pode integrar o enfrentamento de padrões enganosos segundo a agenda?',
'A seção educacional relata propostas para inserir [[discussões críticas de design enganoso, reflexão ética, estratégias de resistência e letramento sobre dark patterns]] nos currículos de IHC, design e UX. A intenção não é apenas ensinar nomes de padrões: é preparar futuros profissionais para identificar e evitar práticas manipulativas, reconhecendo sua responsabilidade pelas interfaces que produzem. A educação é apresentada como uma frente necessária, mas a própria agenda posteriormente ressalta seus limites. Portanto, [[formação ética não deve ser confundida com garantia de poder decisório ou eliminação dos incentivos comerciais]].', edu,
[p(4, 'HCI research has proposed mitigation strategies', 'ethical dimensions of interface design.'), p(10, 'It is important to note', 'more targeted and feasible counter-strategies in the future.')]);

add('O que jogos sérios e persuasivos acrescentam às iniciativas estáticas de conscientização, conforme descrito no position paper?',
'O texto apresenta jogos sérios e persuasivos como contramedidas educacionais que procuram informar e favorecer mudanças por meio de [[experiências imersivas e interativas]]. Diferentemente de instrumentos estáticos, eles podem envolver o jogador em uma experiência que espelha situações de manipulação, tornando a compreensão mais situada na interação. Isso os torna uma abordagem promissora para educação sobre padrões enganosos em jogos. A qualificação é essencial: [[promessa pedagógica e reconhecimento de padrões não equivalem, sozinhos, a resistência efetiva ou proteção duradoura]], razão pela qual o artigo defende avaliar intervenções mais amplas.', edu,
[p(4, 'Researchers have also explored serious and persuasive games', 'deceptive design in games.'), p(4, 'However, research has increasingly highlighted', 'just placing responsibility on users.')]);

add('Como alguém pode reconhecer uma estratégia manipulativa e ainda assim não conseguir resistir a ela, e o que isso muda na agenda de pesquisa?',
'A agenda cita evidência de que usuários conscientes de estratégias manipulativas podem [[sentir-se incapazes de se opor a elas]]. O problema, portanto, não se reduz à ausência de informação: reconhecer um padrão e conseguir agir diante dele são resultados diferentes. Para a pesquisa, isso pede intervenções diversas e avaliação da capacidade efetiva de decisão, evitando depositar toda a responsabilidade no usuário. O artigo usa essa limitação para justificar a expansão do trabalho de IHC além da conscientização. [[Não conclui que educar seja dispensável]], mas que educação isolada pode ser insuficiente.', edu,
[p(4, 'However, research has increasingly highlighted', 'just placing responsibility on users.')]);

add('Por que críticas éticas, normas jurídicas e estudos de saúde precisam de integração para enfrentar padrões enganosos?',
'A seção aponta limites complementares: [[críticas éticas podem permanecer teóricas e sem mecanismos de execução; regulação pode adaptar-se lentamente e encontrar dificuldades entre jurisdições; estudos de saúde nem sempre se transformam em padrões exigíveis]]. Pressões industriais e monetização ainda podem enfraquecer intenções éticas de designers. Por isso, o artigo propõe articular educação, responsabilização no design e coordenação de políticas, com participação de pesquisadores, formuladores de políticas e indústria. A integração é uma direção de pesquisa e ação, [[não um pacote já testado que tenha resolvido esses obstáculos]].', ethical,
[p(5, 'While ethical, legal, and health-focused research', 'commercial logic sustaining DPs in games.'), p(5, 'Taken together, this body of work suggests', 'transparency tools for players.')]);

add('Quais métodos empíricos de IHC são mobilizados pela agenda para compreender necessidades dos jogadores antes de formular contramedidas?',
'O artigo cita [[etnografia, playtesting, experimentos e estudos de experiência do jogador]] para compreender necessidades, contextos, motivações e processos cognitivos, incluindo autonomia, competência e vínculo. Esse conhecimento empírico é apresentado como fundamento para investigar escolhas de design e seus efeitos sobre necessidades humanas. A passagem seguinte trata autonomia e consentimento informado como aspectos a preservar na experiência interativa. Assim, a proposta é conectar compreensão situada dos jogadores à construção e ao teste de soluções; [[os métodos citados não são uma pesquisa empírica executada pelo próprio position paper]].', action,
[p(5, 'HCI, by definition', 'and legislators can legislate against it, but HCI researchers and practitioners'), p(6, 'can look at how to counteract it in practice.', 'consent, viewing these as rights to be upheld within the interactive experience.')]);

add('Que alternativas concretas de apresentação de progressão e compra a agenda usa para explicar uma intervenção no nível da interação?',
'O texto propõe investigar [[como comunicar esforço e recompensa sem grinding que explore o jogador]] e [[como apresentar ofertas de compra respeitando escolha informada, em vez de explorar urgência]]. Esses exemplos tornam observável a contribuição da IHC: formular alternativas de interface e técnicas de interação e submetê-las a avaliação empírica. A questão não é simplesmente condenar toda progressão ou compra, mas examinar como cada mecanismo é apresentado e vivenciado. Os exemplos são possibilidades de investigação; [[o artigo não relata um teste que tenha confirmado a eficácia de uma interface específica]].', action,
[p(6, 'Hence, we as a community can focus', 'test such alternatives.')]);

add('Como a agenda diferencia engajamento sustentável de compulsão sem defender a eliminação de toda monetização?',
'O position paper declara que a tarefa não é eliminar monetização ou mecânicas de engajamento, e sim projetá-las de maneira [[sustentável e ética]]. Defende investigar experiências envolventes por prazer e motivação intrínseca, em vez de compulsão. Entre os espaços de inovação mencionados estão controles explícitos de tempo e dados e interfaces que revelem mecanismos de monetização. A hipótese de trabalho é aproximar respeito ao jogador e objetivos sustentáveis de desenvolvimento. Essa aproximação permanece uma [[possibilidade a examinar e demonstrar]], não uma garantia de resultado comercial.', action,
[p(6, 'The task is not so much to eliminate', 'could be a space for HCI-led innovation.')]);

add('Qual hipótese de relação entre respeito à agência, confiança e sustentabilidade comercial é sugerida pelo artigo, e qual seu limite evidencial?',
'O texto sugere que um jogo envolvente que respeite a agência pode ter maior probabilidade de produzir [[lealdade duradoura e atitudes favoráveis da comunidade]], aspectos que também podem constituir ativos para o negócio. A IHC poderia examinar se experiências baseadas em bem-estar favorecem engajamento genuíno e até ajudam a redefinir objetivos sustentáveis. Contudo, o modo verbal é propositivo: [[o position paper não apresenta dados que demonstrem esse retorno comercial]]. Na arguição, a relação deve ser defendida como hipótese investigável, preservando a tensão real entre incentivos econômicos e proteção do jogador.', action,
[p(6, 'The task is not so much to eliminate', 'could be a space for HCI-led innovation.')]);

add('Por que um léxico compartilhado e metodologias comuns deveriam preceder uma coleção de alternativas éticas?',
'Antes de criar bases cooperativas, a agenda propõe formar [[entendimento compartilhado e metodologias robustas]] para documentar padrões problemáticos e seus equivalentes éticos. Um léxico rico, apoiado em taxonomias bem fundamentadas, permitiria descrever projetos que respeitam a agência de maneira compreensível entre grupos. O artigo sugere diálogo contínuo por oficinas, trilhas em conferências, grupos de interesse e fóruns abertos de cocriação. Assim, o repositório depende de uma prática comunitária anterior e contínua; [[armazenar exemplos sem acordo conceitual não resolve a tradução entre pesquisa e prática]].', collab,
[p(7, 'Before establishing cooperative collections', 'documentation.')]);

add('Como métodos padronizados, mas flexíveis, podem avaliar exemplos de design ético sem reduzir a avaliação ao engajamento?',
'A agenda recomenda princípios compartilhados de verificação empírica que possam acomodar perguntas de pesquisa diferentes e incluam [[bem-estar e engajamento]]. A System Darkness Scale aparece como possível ponto inicial para avaliações quantificáveis, a ser adaptado e combinado com métodos mistos para captar dimensões positivas. O objetivo é demonstrar respeito pelo jogador, [[não apenas otimizar métricas de engajamento]]. Isso exige flexibilidade contextual e cuidado com o que cada instrumento mede. O texto sugere esse desenvolvimento metodológico; não oferece um protocolo final universal nem valida uma adaptação própria da escala.', collab,
[p(7, 'Standardized yet flexible ways', 'engagement metrics.')]);

add('Por que a agenda prioriza formas diversas de colaboração e disseminação em vez de começar por um site estático de padrões?',
'Um repositório dinâmico na web permanece como meta de longo prazo, inspirado em plataformas colaborativas ou documentação aberta, em vez de páginas estáticas controladas por um único pesquisador. Mas o foco imediato proposto é [[diversificar colaboração e disseminação]], permitindo documentação abrangente. A continuidade entre as páginas esclarece que essa documentação deve ir além de layouts e sequências de interação e incorporar fundamentos éticos, construtos psicológicos e validação. A infraestrutura digital, portanto, depende de processos de participação e qualidade; [[sua simples existência não comprova utilidade industrial ou eficácia sobre o bem-estar]].', collab,
[p(7, 'While a dynamic, web-based repository', 'This documentation should go beyond'), p(8, 'visual layouts and interaction sequences.', 'integrity, and evolving nature.')]);

add('Que funções revisão por pares, curadoria com desenvolvedores e versionamento desempenhariam em um repertório compartilhado de design ético?',
'Na proposta, [[revisão por pares, curadoria liderada pela comunidade com participação de desenvolvedores e versionamento]] são mecanismos essenciais para manter qualidade, integridade e evolução do conhecimento compartilhado. Eles acompanham uma documentação que precisa explicitar princípios, construtos psicológicos e validação, permitindo que exemplos sejam discutidos e atualizados em vez de tratados como receitas imutáveis. O artigo não fornece um processo de governança já avaliado: delineia requisitos. A ligação com a prática depende de contribuições qualificadas e manutenção contínua, [[não apenas da publicação inicial de uma coleção]].', collab,
[p(8, 'visual layouts and interaction sequences.', 'integrity, and evolving nature.'), p(8, 'Funding and sustaining such collaborative endeavors', 'development, relevance, and ethical stewardship.')]);

add('Quais incentivos poderiam favorecer a participação inclusiva na documentação colaborativa, segundo o position paper?',
'O artigo propõe processos inclusivos que ofereçam [[valor claro a quem contribui]], como oportunidades de coautoria, reconhecimento pelos pares e formação de uma comunidade de prática de design ético. Os recursos compartilhados também poderiam servir à educação, complementando iniciativas de conscientização com exemplos concretos de alternativas de design. A inclusão, assim, aparece tanto no modo de produzir conhecimento quanto em sua circulação. São sugestões de organização comunitária; [[o texto não relata um experimento que demonstre qual incentivo funciona melhor ou que resolva desigualdades de participação]].', collab,
[p(8, 'To encourage broad participation', 'providing concrete examples of ethical design in action.')]);

add('Que condições financeiras e de governança a agenda considera necessárias para sustentar recursos colaborativos de design ético?',
'O texto antecipa desafios significativos para financiar e sustentar esses esforços. Aponta [[consórcios de pesquisa, parcerias universitárias e financiamento de fundações voltadas à tecnologia ética e ao conhecimento aberto]] como possíveis apoios. Acima deles, ressalta engajamento comunitário continuado e propriedade compartilhada como essenciais ao desenvolvimento, à relevância e à gestão ética de longo prazo. A proposta trata sustentabilidade como problema permanente da infraestrutura de conhecimento, [[sem supor que criar o repositório ou obter uma verba inicial baste para mantê-lo útil e confiável]].', collab,
[p(8, 'Funding and sustaining such collaborative endeavors', 'development, relevance, and ethical stewardship.')]);

add('Como a descentralização da pesquisa pode produzir recomendações especializadas sem perder uma base compartilhada?',
'Segundo a agenda, diferentes grupos podem contribuir com conhecimento sobre [[gêneros de jogo, populações de jogadores e problemas éticos específicos]], como crianças, pessoas em situações de vulnerabilidade, privacidade de dados e monetização justa. Esforços coordenados e plataformas de compartilhamento bem concebidas podem reunir esses conhecimentos e exemplos práticos para a comunidade de desenvolvimento. A descentralização é tratada como uma vantagem potencial, desde que acompanhada por articulação. Não se trata de converter um único exemplo em norma para todos: [[a especialização contextual deve permanecer visível na documentação e na recomendação]].', collab,
[p(8, 'The decentralized nature of research', 'design ethos grounded in respect for the player.')]);

add('Como o exemplo de recompensas de missões diárias mostra a passagem de uma crítica a uma agenda de alternativas testáveis?',
'O position paper retoma achados de Frommel e Mandryk segundo os quais recompensas diárias, embora envolventes, podem ser acompanhadas de [[medo de perder oportunidades ou sensação de obrigação]]. A partir dessa evidência citada, propõe que a comunidade desenvolva, teste e documente sistemas de recompensa alternativos, divulgando exemplos examinados e razões claras de design em canais acessíveis. O movimento é de uma observação de problema para a investigação de uma solução situada. [[O artigo não apresenta um sistema alternativo já validado]], nem conclui que toda recompensa diária seja necessariamente enganosa.', collab,
[p(7, 'To bridge this gap and to advance initiatives like these', 'and general industry use.')]);

add('Que sequência de apoio contextual uma ferramenta para jogadores poderia oferecer além de apenas avisar que existe um padrão enganoso?',
'A agenda descreve ferramentas como extensões ou sobreposições que poderiam [[destacar um possível padrão quando ele aparece, explicar seu mecanismo manipulativo e eventualmente sugerir ações alternativas]] apoiadas em um repertório validado. A intenção seria levar habilidades de reconhecimento para o momento concreto da interação, em vez de separá-las da decisão. O documento também pede respeito à agência, sem impor escolhas. Essa sequência é uma especificação de pesquisa: [[a existência de tipologias e exemplos não demonstra que um detector contextual seja preciso, utilizável ou eficaz]], aspectos que ainda exigem testes.', tools,
[p(8, 'While raising awareness is necessary', 'designing interactive'), p(9, 'software artifacts with real-time support and intervention.', 'repository.'), p(10, 'Of course, these tools', 'experience.')]);

add('Por que induzir o jogador a uma decisão considerada melhor pode contradizer o propósito ético de uma contramedida?',
'O texto formula um limite explícito: a ferramenta não deveria [[enganar o usuário para fazê-lo escolher o que o sistema considera melhor]], porque isso também prejudicaria sua autonomia. Seu propósito seria aumentar a agência por conscientização em tempo real e transformar encontros manipulativos em oportunidades de decisão informada, sem ditar escolhas. A distinção exige avaliar o próprio modo de intervenção, e não apenas sua intenção protetiva. O argumento é normativo e orientador; [[não estabelece que qualquer aviso ou recomendação automaticamente preserve a agência]], pois desenho, contexto e uso continuam relevantes.', tools,
[p(9, 'The advantage provided herein', 'for informed decision-making.')]);

add('Que problema de contorno ou comprometimento das ferramentas protetivas a agenda reconhece, e por que isso importa para sua avaliação?',
'Ao discutir ferramentas para jogadores, o artigo ressalta que [[jogadores avançados ou plataformas podem desenvolver meios de contornar ou comprometer sua eficácia]], retomando a discussão de Xiao e Denoo. Isso impede tratar uma ferramenta como solução definitiva apenas porque identifica padrões em uma demonstração. A proposta mantém o foco em agência e escolhas informadas e, posteriormente, demanda testes empíricos rigorosos de eficácia e facilidade de uso. Assim, a avaliação precisa considerar o uso real e seus limites. [[O texto reconhece a possibilidade de evasão; não demonstra que toda ferramenta será contornada]].', tools,
[p(9, 'The advantage provided herein', 'for informed decision-making.'), p(10, 'Of course, these tools', 'experience.')]);

add('Quais obstáculos de utilidade e aceitação podem fazer uma ferramenta de apoio a desenvolvedores ser ignorada ou contornada?',
'O artigo descreve a dificuldade de construir ferramentas [[inteligentes e sensíveis ao contexto, capazes de sugerir alternativas práticas em vez de notificações triviais]]. Também aponta que desenvolvedores podem ignorá-las ou trabalhar ao redor delas se forem percebidas como limitações à criatividade, excessivamente restritivas ou conflitantes com objetivos financeiros. Portanto, não basta detectar um problema: a ferramenta precisa dialogar com o trabalho real e oferecer apoio compreensível a decisões. A agenda apresenta esses obstáculos como desafios de investigação, [[sem relatar a aceitação de um plugin específico já implementado]].', tools,
[p(9, 'The primary benefit is proactive', 'objectives.')]);

add('Como a cultura de desenvolvimento se relaciona à adoção das ferramentas éticas propostas, além da qualidade técnica do software?',
'O texto afirma que adoção e eficácia dependem da disposição da indústria para incorporar padrões de design ético e apoio correspondente. Mas ressalta que essa integração é [[uma materialização necessária de princípios éticos na cultura de desenvolvimento]], não simplesmente uma técnica para aumentar a eficácia de uma ferramenta. Também exige entendimento de psicologia do jogador e da prática de desenvolvimento, além de testes rigorosos de eficácia e uso. A tecnologia está, assim, situada em práticas e compromissos organizacionais; [[instalar um artefato não demonstra uma mudança cultural nem garante seus resultados]].', tools,
[p(10, 'Of course, these tools', 'experience.')]);

add('Que pesquisa empírica a agenda propõe para compreender a distribuição de conhecimento e poder decisório sobre padrões enganosos nas empresas?',
'O artigo propõe [[surveys em larga escala ou entrevistas com profissionais]], especialmente dos setores mobile e live-ops, para investigar conhecimento sobre padrões enganosos, agência percebida nas decisões e pressões organizacionais. O objetivo é esclarecer como conhecimento e poder de decisão se distribuem entre funções, já que diretrizes de monetização podem vir de acionistas, executivos e equipes de produto ou monetização. Esses resultados poderiam orientar contramedidas mais direcionadas e viáveis. [[São estudos futuros sugeridos pelo position paper]], e não entrevistas ou estimativas de distribuição de poder que ele próprio tenha executado.', tools,
[p(10, 'It is important to note', 'more targeted and feasible counter-strategies in the future.')]);

add('Por que avaliar uma contramedida somente por retenção, duração de sessão ou receita pode perder o objetivo ético definido na agenda?',
'A discussão organizacional observa que decisões de monetização se apoiam em [[retenção, duração de sessão, base de usuários ativos e receita]]. Já a proposta de avaliação ética pede autonomia percebida, justiça, transparência, respeito e bem-estar psicológico. A comparação interna ao artigo mostra que os dois conjuntos de indicadores respondem a perguntas diferentes: crescimento de atividade ou receita, isoladamente, não demonstra respeito ao jogador. O documento propõe examinar sua relação com objetivos sustentáveis, [[sem assumir uma equivalência entre engajamento comercial e benefício psicológico ou que esses objetivos sejam sempre incompatíveis]].', measures,
[p(10, 'It is important to note', 'more targeted and feasible counter-strategies in the future.'), p(11, 'adapting specific player experience instruments', 'counteract them.')]);

add('Por que demonstrar ausência de padrões enganosos ainda não basta para avaliar uma alternativa ética de design?',
'A agenda pede avaliar também [[a eficácia de escolhas éticas em criar uma experiência positiva e envolvente por prazer genuíno, sem coerção]]. Isso amplia a avaliação para além da presença ou ausência de padrões conhecidos. É necessário examinar como a alternativa afeta necessidades, experiência e agência, utilizando dados de jogo, instrumentos refinados e análise qualitativa. A posição não é que qualquer experiência positiva descarte riscos, mas que o conhecimento sobre uma solução precisa ir além de uma lista de problemas evitados. [[A avaliação proposta continua sendo uma tarefa empírica a desenvolver]].', measures,
[p(11, 'Addressing these challenges involves', 'where ethically appropriate.')]);

add('Como telemetria, dados comportamentais e análise qualitativa poderiam se complementar na avaliação de autonomia e manipulação?',
'O texto propõe desenvolver [[telemetria e análises comportamentais que revelem padrões indicativos de autonomia comprometida ou mecânicas manipulativas]], integrando esses dados a perspectivas qualitativas e a instrumentos refinados de experiência do jogador. A combinação permitiria uma avaliação mais abrangente do que apenas observar um indicador isolado. O artigo usa linguagem propositiva e não especifica um sinal comportamental já validado como diagnóstico de manipulação. Portanto, [[dados de uso precisam ser interpretados com contexto e outras evidências]], em vez de automaticamente transformados em medida direta de bem-estar ou autonomia.', measures,
[p(11, 'Addressing these challenges involves', 'where ethically appropriate.')]);

add('Por que a metodologia de avaliação precisa considerar gênero de jogo e modelo de monetização, mesmo quando procura alguma padronização?',
'O artigo pede [[metodologias padronizadas, mas adaptáveis]], para avaliar presença e impacto dos padrões em gêneros e modelos de monetização diversos. Também sugere combinar avaliações de especialistas ajustadas a tipos de jogo e estratégias de monetização com abordagens automatizadas emergentes, quando eticamente apropriadas. A padronização visa comparação e rigor, enquanto a adaptação evita perder particularidades da experiência. Isso é uma direção metodológica, [[não um protocolo universal já validado]], e a automação é apresentada como complementar e condicionada, não como substituição automática de julgamento contextual.', measures,
[p(11, 'Building upon existing frameworks', 'areas for improvement.'), p(11, 'Addressing these challenges involves', 'where ethically appropriate.')]);

add('Como o exemplo “design X, resultado Y, medida Z” define o tipo de recomendação que a agenda deseja oferecer a profissionais?',
'A agenda quer avançar de conselhos gerais para [[recomendações específicas apoiadas empiricamente]], em que se descreva uma escolha de design, o resultado demonstrado e a medida usada para avaliá-lo. O exemplo liga um sistema de recompensas à preservação de autonomia e a um efeito sobre justiça percebida medido por um instrumento identificado. Essa estrutura permite avaliar o alcance da evidência e comparar estudos, em vez de confiar apenas no rótulo “ético”. [[X, Y e Z são espaços ilustrativos no argumento, não uma solução e um efeito já comprovados pelo artigo]].', measures,
[p(11, 'Developing and adapting methods', 'real change in game design practices.')]);

add('Quais quatro linhas articuladas compõem a agenda final de pesquisa e como elas conectam teoria e aplicação?',
'O artigo organiza a chamada em [[desenvolver e validar soluções éticas; criar e avaliar ferramentas de intervenção; refinar métodos de avaliação de impacto; traduzir pesquisa em orientação aplicável aos profissionais]]. A primeira trata de alternativas para mecânicas suscetíveis à exploração; a segunda inclui apoio a jogadores e desenvolvedores; a terceira busca medidas de prevalência, bem-estar e justiça; a quarta examina formatos e canais de tradução. As linhas são interdependentes: soluções precisam de avaliação e circulação prática. [[São perguntas abertas de pesquisa]], sem uma resposta única pronta para todos os jogos e populações.', agenda,
[p(12, 'From our discussion, a research agenda emerges', 'implementation gap between academic research and industry practice?')]);

add('Por que diversidade de participantes, países e perspectivas do Sul Global é parte da agenda, e não apenas uma ampliação numérica da amostra?',
'Na conclusão, o texto propõe combinar [[profundidade qualitativa, rigor quantitativo e colaboração entre pesquisadores, designers, desenvolvedores e jogadores]], incluindo pessoas de contextos e países diferentes e explicitamente a perspectiva do Sul Global. A proposta se conecta ao reconhecimento de que jogos e experiências são diversos e dinâmicos, incompatíveis com soluções definitivas iguais para todos. A diversidade deve participar da produção de conhecimento aplicável, não apenas fornecer mais observações a uma receita pronta. [[A passagem não apresenta uma avaliação intercultural própria]], mas um compromisso orientador das próximas investigações.', agenda,
[p(11, 'This position paper argued', 'as the landscape'), p(12, 'of game design and player experience', 'player-respecting game environments.'), p(12, 'Addressing these questions requires', 'games.')]);

add('Que informação uma documentação de padrão ético precisa acrescentar aos layouts e às sequências de interação?',
'O artigo pede que o registro explicite [[princípios éticos, construtos psicológicos abordados e validação empírica robusta]], em vez de apenas mostrar a interface ou descrever os passos de uso. Isso fornece fundamentos para compreender por que uma alternativa seria desejável e que conhecimento sustenta a recomendação. Revisão por pares, curadoria comunitária com desenvolvedores e versionamento completam a proposta de qualidade. A exigência de validação é especialmente relevante: [[um exemplo visual atraente ou um nome positivo não demonstra respeito à agência nem efeitos benéficos]], que precisam ser investigados no contexto de aplicação.', collab,
[p(7, 'While a dynamic, web-based repository', 'This documentation should go beyond'), p(8, 'visual layouts and interaction sequences.', 'integrity, and evolving nature.')]);

add('Como a responsabilidade do prestador em Safety by Design ajuda a contextualizar as ferramentas preventivas para desenvolvedores propostas na agenda?',
'Como síntese entre os textos, [[a intervenção precisa integrar o processo de desenvolvimento e uma responsabilidade organizacional identificável]]. A agenda propõe ferramentas que sinalizem decisões problemáticas e apoiem alternativas, mas reconhece exigências de cultura, conhecimento e testes. SbD afirma que a segurança não deve recair só no usuário e pede avaliação documentada de riscos e impactos; sua nota de boa prática ilustra revisões antes do lançamento. Uma ferramenta poderia apoiar esse processo, sem substituí-lo. [[Essa é uma articulação analítica para arguição]], não uma ferramenta validada por ambos os trabalhos nem prova de que os exemplos históricos de 2019 sejam eficazes em qualquer jogo.', tools,
[p(9, 'The second type would be developer-supported tools', 'objectives.'), p(10, 'Of course, these tools', 'experience.')],
[related(SBD, 'Principles 1 and 1.6', [ev(SBD, 22, 'Principle 1: Service provider', 'Principle 1.'), ev(SBD, 27, 'Good practice note ( Principle 1.6)', 'market.'), ev(SBD, 27, 'Principle 1.6: Prepare documented risk management', 'exercise good practice when it comes to addressing\n\nsafety risks.')])]);

add('Como a avaliação de eficácia em Safety by Design se relaciona à proposta de medir autonomia e justiça, sem confundir números de atividade com proteção?',
'SbD 3.4 diferencia estatísticas sobre a escala dos relatos de uma [[análise da eficácia de regras e diretrizes para conter condutas danosas]], pedindo avaliação anual e métricas significativas. A agenda, no domínio dos jogos, solicita medidas de autonomia, justiça, transparência, respeito e bem-estar, combinadas com evidência comportamental e qualitativa. A ponte é exigir que os indicadores respondam ao objetivo protetivo, não apenas registrem atividade. [[Não se deve equiparar volume de denúncias, retenção ou duração de sessão a benefício psicológico]]. Os textos operam em escopos diferentes e esta comparação não valida um instrumento único nem transfere automaticamente métricas de moderação para avaliação de jogos.', measures,
[p(11, 'adapting specific player experience instruments', 'counteract them.'), p(11, 'Addressing these challenges involves', 'where ethically appropriate.')],
[related(SBD, 'Principle 3.4', [ev(SBD, 36, 'Principle 3.4: Publish an annual assessment', 'work of the eSafety SbD Framework program.')])]);

add('Que relação pode ser estabelecida entre a colaboração aberta de Safety by Design e o repertório comunitário de alternativas éticas da agenda?',
'SbD 3.3 pede participação de usuários, especialistas independentes e interessados para examinar padrões de segurança e suas consequências; SbD 3.5 inclui investimento e compartilhamento de tecnologias e boas práticas. A agenda acrescenta requisitos para [[documentação de padrões com fundamentos, validação, revisão, curadoria e versionamento]], além de engajamento e propriedade compartilhados. A correlação sugere que colaboração precisa de governança e critérios de qualidade, e não apenas de um lugar para armazenar exemplos. [[São propostas convergentes em escopos distintos]], sem demonstrar que um repositório já produza redução de danos ou que consulta e validação empírica sejam a mesma atividade.', collab,
[p(8, 'visual layouts and interaction sequences.', 'integrity, and evolving nature.'), p(8, 'Funding and sustaining such collaborative endeavors', 'development, relevance, and ethical stewardship.')],
[related(SBD, 'Principles 3.3 and 3.5', [ev(SBD, 35, 'Principle 3.3: Carry out open engagement', 'by best practice before the feature launches.'), ev(SBD, 36, 'Principle 3.5: Commit to innovating', 'new wave of safety-enhancing technology.')])]);

add('Como o inciso sobre uso prolongado do documento local Art. 48 pode ser discutido junto à proposta de engajamento ético da agenda de intervenção?',
'O inciso XX do §10 apresentado no documento local inclui funcionalidades que incentivam permanência prolongada, como rolagem infinita, notificações, recompensas variáveis, recomendações e ofertas limitadas. A agenda propõe investigar [[engajamento por prazer e motivação intrínseca, com controle explícito de tempo e dados e transparência da monetização]], em vez de compulsão. A correlação coloca a função e a experiência do mecanismo em debate: uma lista classificatória aponta elementos a considerar, enquanto a agenda pede alternativas e avaliação. [[A presença de gamificação não prova, por si só, manipulação ou dano]], e o arquivo Art. 48 não está sendo tratado como verificação de vigência jurídica.', action,
[p(6, 'The task is not so much to eliminate', 'could be a space for HCI-led innovation.')],
[related(ART, 'Art. 48, §10, inciso XX', [ev(ART, 4, 'XX – funcionalidades que incentivem', 'promoções e ofertas limitadas, entre outros;')])]);

add('Por que exibir a indicação etária e informá-la de forma clara e acessível nos termos de uso dos fornecedores que hospedam conteúdo de terceiros, conforme o documento local Art. 48, não esgota a ideia de escolha informada da agenda?',
'Os §§5–6 do documento local pedem indicação etária e descritores claros nos momentos de instalação, login e início de uso; o §12 trata da informação nos termos dos fornecedores que hospedam conteúdo de terceiros. A agenda enfatiza [[apoio à agência na interação concreta]], explicando mecanismos e evitando manipular o usuário para uma escolha considerada melhor. A síntese distingue disponibilidade de informação classificatória de capacidade contextual de decidir. [[As obrigações descritas no arquivo não demonstram, sozinhas, compreensão, resistência ou redução de dano]], e as ferramentas da agenda tampouco estão validadas. A comparação não afirma vigência legal nem propõe substituir classificação por avisos automáticos.', tools,
[p(9, 'The advantage provided herein', 'for informed decision-making.'), p(9, 'There are specific concerns to consider.', 'positive gaming experience.')],
[related(ART, 'Art. 48, §§5–6 e §12', [ev(ART, 2, '§5º Os sujeitos mencionados no caput', '§5º deverá ocorrer nas páginas de instalação, login e início de uso.'), ev(ART, 4, '§12 Os termos de uso', 'atribuição realizada pelo Iarc ou outro modelo autorizado.')])]);

add('Qual é a diferença entre considerar controles parentais e moderação na classificação, conforme o documento Art. 48, e demonstrar efeito de uma contramedida em jogos?',
'O §14 apresentado considera controle editorial e curadoria, ferramentas etárias e parentais acessíveis e políticas de moderação; o §15 remete especificações aos Guias Práticos, cujo conteúdo não é completado aqui. Já a agenda propõe [[medir o efeito de elementos e intervenções sobre autonomia, manipulação percebida e bem-estar]], com métodos sensíveis ao contexto. A síntese distingue critérios usados para atribuir uma classificação da evidência necessária para sustentar uma alegação de eficácia. [[Ter uma ferramenta disponível não prova seu uso nem seu efeito psicológico]]. O documento é tratado apenas como fonte local; não se afirma vigência ou que classificação substitua estudos de experiência.', measures,
[p(10, 'Current HCI research excels', 'perceived manipulation, and holistic psychological well-being.'), p(11, 'Building upon existing frameworks', 'areas for improvement.')],
[related(ART, 'Art. 48, §§14–15', [ev(ART, 4, '§14 Para fi ns', 'serviços digitais sobre os conteúdos disponibilizados;'), ev(ART, 5, 'II – a existência', 'de Classi fi cação Indicativa.')])]);

add('Como o creator-consumer divide do artigo CHIP qualifica a confiança em ferramentas de conscientização propostas na agenda?',
'A agenda reconhece que saber identificar manipulação pode não bastar para resistir e propõe apoio contextual que fortaleça agência. CHIP acrescenta uma lente sobre [[vulnerabilidades sistêmicas e preexistentes, como precariedade e barreiras de letramento]], que podem diferir entre criação e consumo dos jogos. A ponte sugere investigar para quem uma ferramenta é compreensível e útil e quais condições limitam a ação, sem reduzir proteção a mais informação. [[Não se pode concluir que todo jogador com pouco letramento seja incapaz de decidir]], nem usar o cenário especulativo como teste de uma intervenção. A relação é analítica e demanda avaliação com contextos e participantes diversos.', edu,
[p(4, 'However, research has increasingly highlighted', 'just placing responsibility on users.'), p(9, 'The advantage provided herein', 'for informed decision-making.')],
[related(CHIP, '2 The Creator-Consumer Divide as a Lens for Understanding Systemic Player Vulnerability', [ev(CHIP, 1, 'This paper proposes the creator-consumer divide', 'This national-scale vulnerability is dis-\ntinct from the challenges within specific US communities.')])]);

add('Como a discussão da agenda sobre KPIs e poder decisório pode dialogar com a automação indiferente e o dashboard especulativo de CHIP?',
'A agenda descreve pressões de retenção, tempo de sessão e receita vindas de funções com poder decisório, podendo limitar a autonomia de designers. CHIP propõe que vulnerabilidades sejam exploradas por direcionamento deliberado ou [[automação indiferente]] e imagina um dashboard que converte condições de Helena em oportunidades de extração. A síntese desloca a análise da intenção de um designer isolado para objetivos, métricas e distribuição de poder. [[O dashboard é ficção crítica, não um sistema observado nem dados empíricos sobre jogadores]]. A aproximação não prova um mecanismo causal comum a todas as empresas; indica questões para investigar governança, práticas e métricas.', tools,
[p(10, 'It is important to note', 'more targeted and feasible counter-strategies in the future.')],
[related(CHIP, '2 The Creator-Consumer Divide; 3 A Speculative Perspective', [ev(CHIP, 1, 'This paper proposes the creator-consumer divide', 'The\ndivide has two nuances.'), ev(CHIP, 2, 'Artifact from the future', 'pending a performative internal ethics review.'), ev(CHIP, 2, 'Ouroboro’s speculative dystopia', 'potential extreme.')])]);

add('Como a inclusão do Sul Global na agenda pode ser aprofundada pela distinção de CHIP entre coleta de dados e parceria equitativa?',
'A agenda conclui pedindo colaboração entre papéis diversos e pessoas de diferentes países, incluindo explicitamente o Sul Global. CHIP desafia a comunidade a [[ir além de tratar contextos não WEIRD apenas como fontes de dados]], construindo parcerias equitativas e cocriando agendas e paradigmas de design. A síntese mostra que ampliar uma amostra e compartilhar poder na definição do problema são dimensões diferentes. Isso dá conteúdo à proposta de pesquisa colaborativa, sem afirmar que ela já superou as desigualdades descritas. [[Ambos formulam chamadas à ação]], e a ficção crítica de CHIP não substitui resultados de uma colaboração ou avaliação intercultural real.', agenda,
[p(12, 'Addressing these questions requires', 'games.')],
[related(CHIP, '4 Toward a Decolonial Game and Play Research', [ev(CHIP, 3, 'that societies like mine', 'willing to try?')])]);

add('Como os limites do levantamento Interact ajudam a distinguir medir prevalência de padrões e avaliar bem-estar, como pede a agenda?',
'Interact analisou aplicativos gratuitos em alta na loja brasileira, com gravações de dez minutos de primeiro uso e tarefas em emulador; reconhece que uso prolongado e ambiente real podem produzir outras observações. A agenda pede métodos para [[avaliar não só presença de padrões, mas seus impactos e a eficácia de alternativas]]. A correlação mostra que uma classificação de interfaces fornece uma linha de base útil, porém não mede automaticamente efeitos psicológicos ou mudanças causadas por uma intervenção. [[Os resultados dos 100 aplicativos não se transferem diretamente a todos os aplicativos ou aos jogos]], e a proposta de avaliação da agenda também requer validação empírica.', measures,
[p(10, 'Current HCI research excels', 'perceived manipulation, and holistic psychological well-being.'), p(11, 'Building upon existing frameworks', 'areas for improvement.')],
[related(INTERACT, '2 Methodology; 5 Limitations', [ev(INTERACT, 4, 'We used BlueStacks 5', 'not purchase any products or services in the apps.'), ev(INTERACT, 8, 'Our scope contains trending free apps', 'flagged the emulator as suspicious for usage.')])]);

add('Como os casos linguísticos de Interact colocam à prova a ideia de conscientização e escolha informada discutida na agenda?',
'Interact descreve [[termos ou política em outro idioma mesmo quando a aplicação está na língua do usuário]], criando uma barreira entre pessoa e informação; também identifica encaminhamento desnecessário a páginas externas. A agenda reconhece que conscientização isolada pode ser insuficiente e propõe apoio contextual que fortaleça a agência sem ditar escolhas. A síntese sugere examinar compreensibilidade e acesso à informação antes de presumir consentimento ou resistência. [[Detectar uma barreira linguística não quantifica seu efeito causal sobre bem-estar]], e alertar sobre ela não demonstra que o problema tenha sido resolvido. Trata-se de comparar achados de aplicativos e uma proposta para jogos, preservando esses escopos.', edu,
[p(4, 'However, research has increasingly highlighted', 'just placing responsibility on users.'), p(9, 'The advantage provided herein', 'for informed decision-making.')],
[related(INTERACT, '3 Results', [ev(INTERACT, 6, 'Our findings also revealed six DP cases', 'persuade the user into an action.')])]);

add('Como o template de Operationalizing Radiant Patterns pode contribuir para a tradução de ideais em exemplos testáveis pedida pela agenda?',
'A agenda solicita exemplos contextuais com princípios éticos, construtos psicológicos, justificativas e validação. Operationalizing oferece [[campos estruturados como problema, contexto, solução, necessidades psicológicas, riscos de aplicação e exemplos de implementação]]. A correlação é que o template pode tornar a hipótese de uma alternativa mais explícita e compartilhável, preparando a discussão e o teste. Entretanto, [[documentar uma hipótese não demonstra seus resultados]]: Operationalizing reconhece ausência de avaliações com jogadores e de viabilidade comercial concreta. A articulação é analítica; não afirma que o template já concluiu a agenda, que um repositório garante adoção ou que os dois textos validaram a mesma intervenção.', collab,
[p(7, 'To bridge this gap and to advance initiatives like these', 'and general industry use.'), p(8, 'visual layouts and interaction sequences.', 'integrity, and evolving nature.')],
[related(OP, '5 Crafting Radiance; 6.5 Study Limitations', [ev(OP, 9, 'Table 1. Structural Template', 'Illustrative games/features using the RP.'), ev(OP, 16, '6.5 Study Limitations', 'financial performance.')])]);

add('Como a função preventiva de Radiant Patterns e seus limites de mensuração refinam o tipo de avaliação de bem-estar solicitado na agenda?',
'Operationalizing desloca o foco para [[preservar necessidades e reduzir riscos previsíveis de frustração]], sem prometer eliminar toda experiência negativa. Ao discutir avaliação, menciona PENS e IMI para aspectos de motivação intrínseca e questiona como separar o efeito de um padrão do restante do jogo. A agenda pede medidas de autonomia, justiça, transparência e bem-estar combinadas a outras evidências. A síntese exige formular o construto e a atribuição do efeito com precisão: [[medir satisfação ou motivação não prova ausência de frustração nem causalidade do padrão]]. Nenhum dos textos apresenta nessa comparação um protocolo definitivo ou efeitos de bem-estar já validados.', measures,
[p(11, 'adapting specific player experience instruments', 'counteract them.'), p(11, 'Addressing these challenges involves', 'where ethically appropriate.')],
[related(OP, '4 Revisiting and Reshaping Game Radiant Patterns; 6.3 The Challenge to Evaluate Players Well-Being', [ev(OP, 7, 'Instead of “aiming to satisfy,”', 'established anti-patterns.'), ev(OP, 15, '6.3 The Challenge to Evaluate Players Well-Being', 'the result of using radiant patterns.')])]);

add('Como o catálogo e a verificação de candidatos de Beyond Dark Patterns tornam mais concreta a preocupação da agenda com léxico e curadoria?',
'A agenda propõe vocabulário compartilhado, documentação fundamentada, revisão por pares, curadoria comunitária e versionamento. Beyond Dark Patterns descreve a necessidade de [[recorrência, coerência estrutural e discussão colaborativa antes de finalizar candidatos]], pois uma observação autoetnográfica isolada pode gerar falso positivo. A correlação torna explícito o que precisa acontecer entre registrar uma ideia e tratá-la como conhecimento de design compartilhável. [[Verificação de candidato não equivale a avaliação longitudinal de bem-estar]]: o trabalho HCI reconhece essa ausência e a necessidade de testar o uso em desenvolvimento ativo. A ponte não afirma que todos os requisitos da agenda já foram cumpridos.', collab,
[p(7, 'Before establishing cooperative collections', 'documentation.'), p(8, 'visual layouts and interaction sequences.', 'integrity, and evolving nature.')],
[related(HCI, '6 Discussion: Radiant Patterns and Industry Practice; 7 Final Remarks', [ev(HCI, 15, 'Besides, identifying these new mechanics', 'observed, analyzed, and discussed collectively.'), ev(HCI, 16, 'This work evolves the RP framework', 'future industry-led verification.')])]);

add('Como invariantes e variantes de Beyond Dark Patterns ajudam a discutir a tensão entre padronização e contexto presente na agenda?',
'A agenda solicita metodologias comparáveis, mas adaptáveis a gêneros, monetização e populações distintas. Beyond Dark Patterns separa [[invariantes que preservam a identidade do padrão e variantes para adaptações contextuais]], além de níveis L1–L3 como base metodológica. O próprio texto esclarece que esses níveis não alegam uma experiência universal: competência, por exemplo, pode ser vivida diferentemente em gêneros distintos. A síntese sugere preservar um compromisso ético rastreável sem apagar a implementação concreta. [[Essa arquitetura não garante eficácia em todas as situações]], e o framework ainda requer avaliação longitudinal e em desenvolvimento ativo; tampouco constitui um protocolo de mensuração já validado pela agenda.', measures,
[p(11, 'Building upon existing frameworks', 'areas for improvement.'), p(12, 'of game design and player experience', 'player-respecting game environments.')],
[related(HCI, '6 Discussion: Radiant Patterns and Industry Practice; 7 Final Remarks', [ev(HCI, 11, 'To ensure scalability of the RP framework', 'through structural criteria.'), ev(HCI, 15, 'By establishing universal levels', 'contextual boundaries identified in the literature.'), ev(HCI, 16, 'This work evolves the RP framework', 'future industry-led verification.')])]);

if (cards.length !== 50) throw new Error(`Expected 50 candidates; got ${cards.length}`);
const allIds = new Set();
let quotes = 0;
const norm = value => value.normalize('NFKC').replace(/\s+/g, ' ').trim();
for (const card of cards) {
  if (allIds.has(card.id)) throw new Error(`Duplicate ID ${card.id}`);
  allIds.add(card.id);
  for (const { articleId, source: ref } of [{ articleId: card.articleId, source: card.source }, ...(card.relatedSources ?? [])]) {
    const doc = docs.get(articleId), original = await fs.readFile(path.join(root, 'artigos', ref.file));
    if (createHash('sha256').update(original).digest('hex') !== doc.sha256) throw new Error(`Source changed ${articleId}`);
    for (const quote of ref.evidence) {
      if (!doc.pages.some(page => ref.pages.includes(page.page) && norm(page.text).includes(norm(quote)))) throw new Error(`Missing evidence ${card.id}`);
      quotes++;
    }
  }
}
await fs.writeFile(path.join(out, `${main}.json`), JSON.stringify(cards, null, 2) + '\n', 'utf8');
console.log(`${cards.length} candidates; ${cards.filter(card => card.kind === 'direct').length} direct; ${cards.filter(card => card.kind === 'synthesis').length} synthesis; ${quotes} literal quotes; all source hashes verified. Not semantic approval.`);
